let jpReadingId=jpReadings[0].id,jpKanaType=1,jpKanaSelected='あ',jpKanaQuiz=null,jpConversationId='station',jpExamLevel=jpStudyState.level,jpWorkspaceMessage='',jpAudioPlaying=null,jpRecording=null,jpRecordingStream=null,jpRecordingUrl='',jpRecordingStatus='尚未录音。';
function jpModuleCards(){return `<section class="jp-section"><h2>按用途选择学习方式</h2><div class="jp-module-grid">${jpModules.map(([id,title,desc],i)=>`<button data-jp="pane" data-pane="${id}" class="jp-module-card"><small>${String(i+1).padStart(2,'0')}</small><h3>${title}</h3><p>${desc}</p></button>`).join('')}</div></section>`;}
const jpPreviousToday=jpTodayHTML;jpTodayHTML=function(){return jpPreviousToday().replace('<section class="jp-section">',jpModuleCards()+'<section class="jp-section">');};
jpNav=function(){return `<div class="jp-top-links"><button class="text-button" data-jp="pane" data-pane="today">日语首页</button><button class="text-button" data-jp="pane" data-pane="search">查词</button><button class="text-button" data-jp="pane" data-pane="workbench">工作台</button><details class="jp-all-modules"><summary>全部功能</summary><div class="jp-module-menu">${jpModules.map(([id,t])=>`<button data-jp="pane" data-pane="${id}" ${jpPane===id?'aria-current="page"':''}>${t}</button>`).join('')}<button data-jp="pane" data-pane="review">复习安排</button></div></details></div>`;};
function jpReadingMarkup(text,annotated){if(!annotated)return esc(text);const words=[...jpWords].filter(w=>!w.custom).sort((a,b)=>b.word.length-a.word.length),parts=[];let i=0;while(i<text.length){const w=words.find(w=>text.startsWith(w.word,i));if(w){parts.push(`<button class="jp-inline-word" data-jp="word" data-id="${w.id}"><ruby>${esc(w.word)}<rt>${esc(w.reading)}</rt></ruby></button>`);i+=w.word.length;}else{parts.push(esc(text[i]));i++;}}return parts.join('');}
function jpReadingHTML(){const r=jpReadings.find(r=>r.id===jpReadingId),p=jpStudyState.readingProgress[r.id]||(jpStudyState.readingProgress[r.id]={annotated:false,translated:false,answer:null,checked:false});return `${jpHeader('读一小段，理解完整意思。','READING')}<div class="jp-reading-choices">${jpReadings.map(r=>`<button data-jp="reading" data-id="${r.id}" ${r.id===jpReadingId?'aria-current="page"':''}>${r.level} / ${r.title}</button>`).join('')}</div><article class="jp-reading-article"><span class="chip">${r.level} / 本站原创短文</span><h2>${r.title}</h2><div class="jp-actions"><button data-jp="reading-ruby">${p.annotated?'隐藏精选词注音':'显示精选词注音'}</button><button data-jp="reading-translation">${p.translated?'收起中文翻译':'对照中文翻译'}</button><button data-jp="speak" data-text="${esc(r.text)}">合成朗读全文</button></div><div class="jp-passage" lang="ja">${jpReadingMarkup(r.text,p.annotated)}</div>${p.translated?`<p class="jp-reading-translation">${r.translation}</p>`:''}<p class="small-note">注音覆盖本站精选词；点击注音词可查看词条。全文朗读使用设备合成语音，暂无真人全文录音。</p><fieldset><legend>${r.question}</legend>${r.options.map((x,i)=>`<label class="hub-option"><input type="radio" name="jp-reading-answer" value="${i}" ${p.answer===i?'checked':''}><span>${x}</span></label>`).join('')}</fieldset><button class="primary" data-jp="reading-grade" ${p.answer===null?'disabled':''}>核对理解</button>${p.checked?`<div class="jp-answer-feedback" role="status"><h3>${p.answer===r.answer?'理解正确':'再回到原文找依据'}</h3><p>${r.explanation}</p></div>`:''}</article>`;}
function jpKanaHTML(){const selected=jpKanaRows.find(r=>r[jpKanaType]===jpKanaSelected)||jpKanaRows[0],q=jpKanaQuiz;return `${jpHeader('先听一拍，再认一个字。','KANA')}<p>平假名与片假名是同一组音的两套字形。这里列出 46 个基本假名；浊音、拗音、长音和促音在课程中继续学习。</p><div class="jp-actions"><button data-jp="kana-type" data-type="1" ${jpKanaType===1?'aria-current="page"':''}>平假名</button><button data-jp="kana-type" data-type="2" ${jpKanaType===2?'aria-current="page"':''}>片假名</button><button class="secondary" data-jp="lesson" data-id="hira">先看五十音入门课</button></div><div class="jp-kana-grid">${jpKanaCells.map(r=>r?`<button data-jp="kana" data-char="${r[jpKanaType]}" ${jpKanaSelected===r[jpKanaType]?'aria-current="page"':''}><b lang="ja">${r[jpKanaType]}</b><small>${r[0]}</small></button>`:'<span class="jp-kana-empty" aria-hidden="true"></span>').join('')}</div><div class="jp-kana-selected"><b lang="ja">${selected[jpKanaType]}</b><span>${selected[0]} / 平假名 ${selected[1]} / 片假名 ${selected[2]}</span><button class="primary" data-jp="speak" data-text="${selected[1]}">播放这一拍</button><p class="small-note">は、へ、を作助词时读音有特别规则；を通常读 o。罗马字只是辅助，优先建立字形与日语发音的对应。</p></div><section class="jp-section"><h2>辨认练习</h2><button class="secondary" data-jp="kana-question">${q?'换一道题':'开始辨认练习'}</button>${q?`<p>哪一个${jpKanaType===1?'平假名':'片假名'}对应 <b>${q.roman}</b>？</p><div class="jp-actions">${q.options.map(x=>`<button data-jp="kana-answer" data-char="${x}" lang="ja">${x}</button>`).join('')}</div>${q.feedback?`<p role="status">${esc(q.feedback)}</p>`:''}`:''}</section><section class="jp-section"><h2>看笔顺，自己描写</h2><p>先看图中笔画编号，再在空白练习格中描写；这里只提供参考和画板，不自动评分笔顺。</p><div class="jp-actions">${[...('あいうえお日月人山川水本')].map(c=>`<button data-jp="stroke" data-char="${c}">${c}</button>`).join('')}</div><div class="jp-writing-tools"><img id="jp-stroke-image" src="data/japanese/strokes/${'あ'.codePointAt(0).toString(16).padStart(5,'0')}.svg" alt="あ的笔顺图"><canvas id="jp-tracing" width="320" height="320" aria-label="手写练习画板；使用鼠标或手指绘制"></canvas></div><button class="secondary" data-jp="clear-trace">清空练习格</button><p class="small-note">笔顺图来自 <a href="https://github.com/KanjiVG/kanjivg" target="_blank" rel="noopener noreferrer">KanjiVG</a> / Ulrich Apel，CC BY-SA 3.0。原图版权说明保留在文件中。</p></section>`;}
function jpPrepareCanvas(){const c=$('jp-tracing');if(!c)return;const ctx=c.getContext('2d');ctx.strokeStyle=getComputedStyle(document.documentElement).getPropertyValue('--ef-ink').trim();ctx.lineWidth=5;ctx.lineCap='round';let drawing=false;const at=e=>{const r=c.getBoundingClientRect();return [(e.clientX-r.left)*c.width/r.width,(e.clientY-r.top)*c.height/r.height];};c.addEventListener('pointerdown',e=>{drawing=true;c.setPointerCapture(e.pointerId);ctx.beginPath();ctx.moveTo(...at(e));});c.addEventListener('pointermove',e=>{if(!drawing)return;ctx.lineTo(...at(e));ctx.stroke();});c.addEventListener('pointerup',()=>drawing=false);c.addEventListener('pointercancel',()=>drawing=false);}
function jpExamPool(level){const words=jpWords.filter(w=>w.level===level&&!w.custom),wordQuestions=words.map((w,i)=>{const other=words.filter(x=>x.id!==w.id).slice((i+1)%Math.max(1,words.length-4),(i+1)%Math.max(1,words.length-4)+3),options=[w.meaning,...other.map(x=>x.meaning)],shift=i%options.length;return {id:'word:'+w.id,prompt:'「'+w.word+'」的意思是？',options:[...options.slice(shift),...options.slice(0,shift)],answer:(options.length-shift)%options.length,explanation:w.reading+' / '+w.meaning+'。'+w.note,wordId:w.id};}),courses=hubCurriculum.japanese.filter(c=>c.section===level).map(c=>({...jpLessonQuestion(c),id:'lesson:'+c.id,lessonId:c.id}));return [...wordQuestions,...courses];}
function jpStartExam(mistakesOnly=false){const pool=jpExamPool(jpExamLevel),words=pool.filter(q=>q.wordId),lessons=pool.filter(q=>q.lessonId),questions=mistakesOnly?pool.filter(q=>jpStudyState.mistakes[q.id]).slice(0,20):[...words.slice(0,5),...lessons.slice(0,5)];if(!questions.length){toast('这个等级暂时没有待复习错题。');return;}jpStudyState.exam={level:jpExamLevel,ids:questions.map(q=>q.id),index:0,answers:[],selected:null,graded:false,finished:false,saved:false};jpSave();render();}
function jpExamCurrent(){const e=jpStudyState.exam;return e&&!e.finished?jpExamPool(e.level).find(q=>q.id===e.ids[e.index]):null;}
function jpExamHTML(){const e=jpStudyState.exam,q=jpExamCurrent();return `${jpHeader('知道为什么，再选答案。','PRACTICE TEST')}<p>本站原创分级练习，不是 JLPT 历年真题，也不按官方量尺估分。每题提交后会说明依据，错误会进入本等级错题记录。</p><div class="jp-actions"><label>练习等级<select id="jp-exam-level">${jpLevels.map(l=>`<option ${l===jpExamLevel?'selected':''}>${l}</option>`).join('')}</select></label><button class="secondary" data-jp="exam-start">开始 10 题练习</button><button class="text-button" data-jp="exam-mistakes">复习本等级错题</button></div>${q?`<section class="jp-exam-sheet"><span class="chip">${e.level} / ${e.index+1} / ${e.ids.length}</span><h2>${esc(q.prompt)}</h2><fieldset><legend>先自己判断，再提交核对。</legend>${q.options.map((x,i)=>`<label class="hub-option"><input type="radio" name="jp-exam-answer" value="${i}" ${e.selected===i?'checked':''}><span>${esc(x)}</span></label>`).join('')}</fieldset><button class="primary" data-jp="exam-grade" ${e.selected===null?'disabled':''}>提交这一题</button>${e.graded?`<div class="jp-answer-feedback" role="status"><h3>${e.selected===q.answer?'回答正确':'还没答对，先读解释'}</h3><p>${esc(q.explanation)}</p><button class="primary" data-jp="exam-next">${e.index===e.ids.length-1?'查看本轮结果':'下一题'}</button></div>`:''}</section>`:e?.finished?`<section class="jp-exam-sheet"><h2>本轮答对 ${e.answers.filter(a=>a.correct).length} / ${e.ids.length} 题</h2><p>分数只描述这轮练习，不代表考试能力等级。可以进入错题回顾，或回到课程补充理解。</p><button class="primary" data-jp="exam-mistakes">回顾本等级错题</button></section>`:'<p class="jp-empty">选择程度后开始。练习进度会保存在本机，离开后可继续。</p>'}<p class="small-note">需要了解正式考试题型，可看 <a href="https://www.jlpt.jp/samples/forlearners.html" target="_blank" rel="noopener noreferrer">JLPT 官方样题</a>；官方题目与本站原创练习分开。</p>`;}
function jpConversationHTML(){const c=jpConversations.find(c=>c.id===jpConversationId),p=jpStudyState.conversationProgress[c.id]||(jpStudyState.conversationProgress[c.id]={draft:'',answer:null,checked:false});return `${jpHeader('先听，再自己说一句。','CONVERSATION')}<div class="jp-actions">${jpConversations.map(c=>`<button data-jp="conversation" data-id="${c.id}" ${c.id===jpConversationId?'aria-current="page"':''}>${c.title}</button>`).join('')}</div><section class="jp-dialogue"><h2>${c.title}</h2><p>${c.role}</p><article><small>你的表达</small><p lang="ja">${c.prompt}</p><p>${c.translation}</p><button class="secondary" data-jp="speak" data-text="${c.prompt}">合成示范发音</button></article><article><small>对方回应</small><p lang="ja">${c.reply}</p><p>${c.replyZh}</p><button class="text-button" data-jp="speak" data-text="${c.reply}">合成回应发音</button></article><label for="jp-conversation-draft">试着写下你自己的表达</label><textarea id="jp-conversation-draft" rows="4" maxlength="1500">${esc(p.draft)}</textarea><div class="jp-actions"><button class="secondary" data-jp="record">${jpRecording?.state==='recording'?'结束录音':'录下自己读的一遍'}</button>${jpRecordingUrl?`<a href="${jpRecordingUrl}" download="japanese-practice.webm">下载本次录音</a>`:''}</div><p role="status">${esc(jpRecordingStatus)}</p>${jpRecordingUrl?`<audio controls src="${jpRecordingUrl}" preload="metadata"></audio>`:''}<p class="small-note">这是脚本情景练习，不是 AI 自由对话；录音仅供自己回听，不评分发音。临时录音请下载保存，刷新后不会保留。</p><fieldset><legend>${c.question}</legend>${c.options.map((x,i)=>`<label class="hub-option"><input type="radio" name="jp-conversation-answer" value="${i}" ${p.answer===i?'checked':''}><span>${x}</span></label>`).join('')}</fieldset><button class="primary" data-jp="conversation-grade" ${p.answer===null?'disabled':''}>检查场景理解</button>${p.checked?`<div class="jp-answer-feedback"><h3>${p.answer===c.answer?'理解正确':'再想想角色与目的'}</h3><p>${c.explanation}</p></div>`:''}</section>`;}
async function jpToggleRecording(){if(jpRecording?.state==='recording'){jpRecording.stop();jpRecordingStream?.getTracks().forEach(t=>t.stop());return;}if(!navigator.mediaDevices?.getUserMedia||typeof MediaRecorder==='undefined'){jpRecordingStatus='当前浏览器不支持网页录音，可使用手机录音机回听自己的发音。';render();return;}try{jpRecordingStream=await navigator.mediaDevices.getUserMedia({audio:true});const chunks=[];jpRecording=new MediaRecorder(jpRecordingStream);jpRecording.ondataavailable=e=>{if(e.data.size)chunks.push(e.data);};jpRecording.onstop=()=>{if(jpRecordingUrl)URL.revokeObjectURL(jpRecordingUrl);jpRecordingUrl=URL.createObjectURL(new Blob(chunks,{type:jpRecording.mimeType}));jpRecordingStatus='录音完成，可回听或下载；未上传服务器。';jpRecordingStream?.getTracks().forEach(t=>t.stop());if(view==='japanese'&&jpPane==='conversation')render();};jpRecording.start();jpRecordingStatus='正在本机录音，请读完后点击“结束录音”。';render();}catch{jpRecordingStatus='没有获得麦克风权限。可以在网站权限中允许录音，或继续文字练习。';render();}}
function jpWorkbenchHTML(){return `${jpHeader('把学习材料，整理成自己的。','WORKBENCH')}<div class="jp-workbench-grid"><section><h2>个人词书导入</h2><p>支持 CSV、JSON 或包含词表与音频的 ZIP。文件只保存在当前浏览器，不发布到公共网站，也不上传原词库与录音。</p><input id="jp-import-file" type="file" accept=".csv,.json,.zip"><button class="secondary" data-jp="import-template">下载 CSV 模板</button><p class="small-note">列名：单词、假名、释义、词性、日文例句、例句译文、备注、音频。音频填写 ZIP 内文件名；支持 MP3、WAV、OGG、M4A。每次最多 5000 词，压缩包不超过 50 MB。不执行书源脚本或登录接口。</p><p id="jp-import-status" role="status">${esc(jpWorkspaceMessage||'导入前请确认文件可供你个人使用；清除站点数据会移除本机导入材料。')}</p><button class="text-button" data-jp="pane" data-pane="saved">打开我的词单与笔记</button></section><section><h2>学习资料</h2><ul class="jp-resource-links"><li><a href="https://www.irodori.jpf.go.jp/" target="_blank" rel="noopener noreferrer">国际交流基金《彩》</a><p>生活日语教材与官方真人音频，在来源页面使用。</p></li><li><a href="https://www.jlpt.jp/samples/forlearners.html" target="_blank" rel="noopener noreferrer">JLPT 官方样题</a><p>核对正式考试题型；本站练习不冒充历年真题。</p></li><li><a href="https://www.mojidict.com/share-center" target="_blank" rel="noopener noreferrer">MOJi 词单与已购内容</a><p>可继续在官方平台使用自己的购买权益。个人导出资料可在左侧导入。</p></li></ul></section></div><section class="jp-section"><h2>已经融合进课堂的开源材料</h2><ul><li>OpenJLPT：分级词库、汉字与例句，查词中可按等级读取。<a href="data/japanese/NOTICE.md" target="_blank">署名与许可</a>。</li><li>KanjiVG：五十音与汉字笔顺图，已放在书写练习中。CC BY-SA 3.0。</li><li>Wikimedia Commons / Lingua Libre：部分假名和单词的授权录音，本地播放。<a href="audio/japanese/NOTICE.json" target="_blank">逐条录音来源与许可</a>。</li></ul><p class="small-note">MOJi 的公开页面仅用于参考分类和学习流程；其词库、录音、付费课程没有被复制到公共站点。</p></section>`;}
const jpWorkspaceBeforeHTML=jpHTML;jpHTML=function(){const custom={reading:jpReadingHTML,kana:jpKanaHTML,exam:jpExamHTML,conversation:jpConversationHTML,workbench:jpWorkbenchHTML}[jpPane];return custom?`<main class="hub-main jp-main">${jpNav()}${custom()}</main>`:jpWorkspaceBeforeHTML();};
const jpLanguageTerms={'助词':'接在词语后，用来说明它在句子中的关系。例如を常标记动作对象，で可标记动作地点。不要只背成一个固定中文译词。','主题':'这句话主要在谈论什么。日语常用は引出主题；主题与动作的执行者不一定相同。','主语':'句子中与谓语对应的人或事物，常用が标记。与“正在谈论的话题”要区分。','谓语':'说明做什么、是什么或怎么样，是理解句子结论的关键。','辞书形':'词典里列出的动词基本形式，例如食べる、行く。它不是ます形。','ます形':'礼貌表达中以ます结尾的动词形式，例如食べます、行きます。','て形':'动词的一种变化形式，例如食べて、行って，常用于连接动作或接请求表达。不同动词变化规则不同。','た形':'动词的一种变化形式，例如食べた、行った。常用于过去或完成，也会进入其他语法结构。','ない形':'表达动词否定的一种形式，例如食べない、行かない。','普通形':'与礼貌形式相对的一组形式，包含非过去、过去、肯定、否定，并不只等于辞书形。','礼貌体':'使用です、ます等形式的表达方式。应结合人物关系和场合选择，并注意前后一致。','接续':'一个语法表达前面接什么形式，例如名词、动词辞书形或动词た形。它不是网络连接。','音读':'汉字在日语中的一类读法，多源自历史上吸收的汉字音；要结合具体词学习。','训读':'把日语固有词义与汉字对应的一类读法，例如山读やま；同一字可有不同读法。','拗音':'像きゃ、しゅ这样的组合，小ゃゅょ和前一个假名合成一拍，不要拆成两拍读。','促音':'用小っ表示的一拍停顿，例如きって。停顿也占时间，不能直接省略。','长音':'把前面的音再延长一拍。长短音可能区别词义，例如おばさん与おばあさん。','一拍':'日语节奏的一小格。长音、促音、ん通常各占一拍；きゃ这样的拗音整体算一拍。'};
const jpTermsBeforeLesson=jpLessonHTML;jpLessonHTML=function(){const html=jpTermsBeforeLesson(),page=jpLessonPages()[jpLessonProgress(jpLesson().id).page],text=(page.paragraphs||[]).join(' ')+page.title,terms=Object.entries(jpLanguageTerms).filter(([term])=>text.includes(term));if(!terms.length)return html;const glossary=`<details class="jp-language-terms"><summary>这页的术语解释 / ${terms.length}</summary><dl>${terms.map(([term,meaning])=>`<dt>${term}</dt><dd>${meaning}</dd>`).join('')}</dl></details>`;return html.replace('</article><div class="reading-pager',glossary+'</article><div class="reading-pager');};
const jpWorkspaceBeforeRender=render;render=function(){if(jpRecording?.state==='recording'&&(view!=='japanese'||jpPane!=='conversation')){jpRecording.stop();jpRecordingStream?.getTracks().forEach(t=>t.stop());}jpWorkspaceBeforeRender();if(view==='japanese')jpPrepareCanvas();};
document.addEventListener('click',e=>{const b=e.target.closest('[data-jp]');if(!b||b.disabled)return;const d=b.dataset,a=d.jp;
 if(a==='reading'){jpReadingId=d.id;render();}
 if(a==='reading-ruby'||a==='reading-translation'){const p=jpStudyState.readingProgress[jpReadingId];if(a==='reading-ruby')p.annotated=!p.annotated;else p.translated=!p.translated;jpSave();render();}
 if(a==='reading-grade'){const p=jpStudyState.readingProgress[jpReadingId];if(p.answer!==null){p.checked=true;jpSave();render();}}
 if(a==='kana-type'){jpKanaType=Number(d.type);jpKanaSelected=jpKanaRows[0][jpKanaType];jpKanaQuiz=null;render();}
 if(a==='kana'){jpKanaSelected=d.char;render();jpPlayAudio(jpKanaRows.find(r=>r[jpKanaType]===d.char)[1]);}
 if(a==='kana-question'){const index=Math.floor(Math.random()*jpKanaRows.length),r=jpKanaRows[index],other=[jpKanaRows[(index+7)%46],jpKanaRows[(index+19)%46],jpKanaRows[(index+31)%46]],choices=[r,...other].map(x=>x[jpKanaType]);const shift=index%4;jpKanaQuiz={roman:r[0],answer:r[jpKanaType],options:[...choices.slice(shift),...choices.slice(0,shift)],feedback:''};render();}
 if(a==='kana-answer'&&jpKanaQuiz){jpKanaQuiz.feedback=d.char===jpKanaQuiz.answer?'答对了：'+jpKanaQuiz.answer+' / '+jpKanaQuiz.roman:'还没答对。再对照上面的字形与读音。';render();}
 if(a==='stroke'){$('jp-stroke-image').src='data/japanese/strokes/'+d.char.codePointAt(0).toString(16).padStart(5,'0')+'.svg';$('jp-stroke-image').alt=d.char+'的笔顺图';}
 if(a==='clear-trace'){const c=$('jp-tracing');c?.getContext('2d').clearRect(0,0,c.width,c.height);}
 if(a==='exam-start')jpStartExam(false);if(a==='exam-mistakes')jpStartExam(true);
 if(a==='exam-grade'){const e=jpStudyState.exam,q=jpExamCurrent();if(q&&e.selected!==null){const correct=e.selected===q.answer;e.graded=true;e.answers[e.index]={id:q.id,selected:e.selected,correct};if(correct)delete jpStudyState.mistakes[q.id];else jpStudyState.mistakes[q.id]=true;jpSave();render();}}
 if(a==='exam-next'){const x=jpStudyState.exam;if(x?.graded){x.index++;x.selected=null;x.graded=false;if(x.index>=x.ids.length){x.finished=true;if(!x.saved){jpStudyState.examHistory.push({date:Date.now(),level:x.level,total:x.ids.length,correct:x.answers.filter(a=>a.correct).length});jpStudyState.examHistory=jpStudyState.examHistory.slice(-30);x.saved=true;}}jpSave();render();}}
 if(a==='conversation'){jpConversationId=d.id;render();}
 if(a==='conversation-grade'){const p=jpStudyState.conversationProgress[jpConversationId];if(p.answer!==null){p.checked=true;jpSave();render();}}
 if(a==='record')jpToggleRecording();
});
document.addEventListener('change',e=>{if(e.target.name==='jp-reading-answer'){const p=jpStudyState.readingProgress[jpReadingId];p.answer=Number(e.target.value);p.checked=false;jpSave();render();}if(e.target.name==='jp-exam-answer'){jpStudyState.exam.selected=Number(e.target.value);jpStudyState.exam.graded=false;jpSave();render();}if(e.target.id==='jp-exam-level'){jpExamLevel=e.target.value;jpSave();render();}if(e.target.name==='jp-conversation-answer'){const p=jpStudyState.conversationProgress[jpConversationId];p.answer=Number(e.target.value);p.checked=false;jpSave();render();}});
document.addEventListener('input',e=>{if(e.target.id==='jp-conversation-draft'){jpStudyState.conversationProgress[jpConversationId].draft=e.target.value.slice(0,1500);jpSave();}});
render();
